      "description": "粉皮煮入汤中，配荷包蛋与青菜，是丽水景宁畲乡常见的早餐形式，一碗里有主食、蛋和蔬菜。",
      "detail": "景宁畲族自治县属丽水，粉皮入汤后滑韧，荷包蛋与青菜增加鲜味和颜色。一碗兼有主食、蛋与菜，呈现畲乡日常早餐的组合。",
      "sources": [
        "read-2ac5aaf54225d7"
      ],
