      "description": "米饭与鸡蛋、虾仁、火腿等翻炒，讲究米粒松散而各类配料细碎均匀，是扬州的代表饭食。",
      "detail": "扬州炒饭将米饭、鸡蛋与细切配料一起翻炒，强调米粒松散又能彼此融合。不同餐馆会调整虾仁、火腿等配料，但饭与菜合为一盘的主食形式一直很鲜明。",
