      "description": "无为板鸭也称无为熏鸭，以鸭肉加工后增加熏制香气，切开后可同时感到咸香、肉香和烟熏风味。",
      "detail": "无为现为芜湖代管县级市，地方板鸭又称无为熏鸭。鸭肉熟制与熏香相结合，外皮、瘦肉和脂肪带来不同口感，切块后常作冷盘。",
