      "type": "staples",
      "kind": "糯米圆子甜汤",
      "description": "芜湖的街头甜食，把白糯米粉做成小圆子，煮熟后连汤加入酒酿，入口软糯，带发酵米香和清甜。",
      "detail": "“水子”是当地对这种小圆子的叫法。它的主体是米粉圆子和甜酒酿，与以茶汤、牛奶为基础的奶茶不是同一类饮品。",
