      "city": "马鞍山",
      "name": "石臼湖螃蟹",
      "type": "ingredients",
      "kind": "当涂湖鲜",
      "description": "石臼湖沿岸的河蟹是当涂地方水产代表，秋季常以清蒸等方式呈现，重在蟹肉、蟹黄的自然鲜味。",
      "detail": "石臼湖跨苏皖两省，马鞍山这一条对应当涂沿湖区域。共享湖区并不意味着某一城市独占产地，购买时仍需辨认实际来源。",
