      "kind": "湖区腌鸭蛋",
      "description": "与当涂湖阳相关的鸭蛋加工食品，蛋黄油润松沙，蛋白咸鲜，常与粥饭搭配，也有地方包装产品。",
      "detail": "“石臼湖”牌产品与湖阳地方禽业相联系。蛋黄颜色是产品外观特点，咸鸭蛋的风味来自腌制，不能把它与鲜鸭蛋混作同一食品。",
