      "description": "含山昭关一带的地方茶名，叶片细小匀嫩，泡开后汤色清亮，风味清鲜而有茶叶本身的浓度。",
      "detail": "昭关位于含山县，现属马鞍山市。它补足的是江北地方茶区的具体名称，不能只用“安徽茶”把各处的产区差异抹去。",
