      "type": "alcohol",
      "kind": "地方酿酒",
      "description": "含山运漕的地方酒与古镇商贸、水运生活相联系，酿造传统是理解这座沿河集镇日常饮食的一条线索。",
      "detail": "运漕现属马鞍山含山县，古镇与沿河商贸、水运往来相连。地方酿酒、谷物交易与日常佐餐相互联系，具体品牌酒款各有自己的风格。",
