      "description": "含山环峰一带的河汊、圩区出产菱角，果肉可煮熟直接吃，也可与豆腐、肉类等一起烧，带淀粉的粉糯感。",
      "detail": "含山环峰一带河汊、圩区提供菱角生长环境，熟后果肉带粉糯口感。它可直接煮食，也能配豆腐、肉类烧制，呈现江淮水网的时令味道。",
