      "description": "濉溪临涣的地方烧肉，与当地酱菜加工传统相连，肉在酱汁中烧入味，成菜香浓，兼有肉脂与发酵酱香。",
      "detail": "“培乳肉”不是乳制品，名字不能用于判断原料分类。它更适合沿着临涣酱园、酱汁与猪肉烹调的关系来理解。",
