      "type": "staples",
      "kind": "硬面蒸食",
      "description": "濉溪百善的硬面大卷，面团较紧实，蒸熟后耐嚼，麦香随着咀嚼释放，是当地集镇常见的扎实主食。",
      "detail": "百善位于濉溪古隋堤沿线，集镇生活与面食经营相连。硬面团蒸熟后组织紧实、耐嚼，小麦香在咀嚼中逐渐释放。",
