      "description": "淮北常见的油酥烧饼，饼皮金黄、薄层相叠，咬开有明显的酥脆感，面香与油酥香结合在一起。",
      "detail": "油酥在面皮之间形成层次，烘烤使外层变得干爽。各地都有烧饼，淮北这一项记录的是当地吃法，不宣称唯一发源地。",
