      "description": "濉溪的丁家壮馍，体形厚实，外层烙得焦黄，内里紧实有筋力，切开后适合慢慢咀嚼出小麦香气。",
      "detail": "壮馍饼体较厚，需让火候慢慢进入内部，烙熟后外层焦香、内瓤紧实。它是濉溪地方厚面饼，与轻薄酥皮烧饼呈现不同面食口感。",
