      "description": "临涣镇的烧饼常带芝麻与葱香，饼皮酥、内瓤柔，有油酥、马蹄、千层等不同形态，是当地面食的一组做法。",
      "detail": "临涣镇面食有油酥、马蹄、千层等不同形态，制坯、蘸芝麻和炉烤形成外层香气。葱香、芝麻香与柔软内瓤相互配合。",
