      "city": "铜陵",
      "name": "糖醋白姜",
      "type": "seasoning",
      "kind": "白姜腌制品",
      "description": "铜陵白姜加工成的糖醋食品，以脆嫩姜片结合糖醋汁，酸甜中仍留姜的辛香，是当地姜制品的明确品种。",
      "detail": "地方报道列出了糖醋、酱汁、黑醋等白姜加工方向。这里选择有代表性的糖醋白姜一项，不把几种相近酱汁机械拆成多张卡。",
      "sources": [
        "city-99df792602efb6"
      ],
      "id": "flavor-anhui-dce2ae5e64"
