      "description": "安庆把糯米处理后炒制成松脆米粒，既能直接吃米香，也常以热鸡汤冲泡，形成鸡汤泡炒米的地方吃法。",
      "detail": "炒米遇汤后逐渐变软，同时把米香融入汤里。它与糖浆黏合成块的冻米糖工艺不同，一松一软之间体现当地饮食习惯。",
