      "description": "界首地方的牛肉食品，以黄牛肉配香料卤煮等工序制作，肉质熟烂而仍有嚼感，口味咸鲜、香气醇厚。",
      "detail": "黄牛肉在香料卤汁中逐渐熟软，部分地方做法再经煨制、油炸。肉味、香辛料与外层香气相结合，形成阜阳界首的熟肉风味。",
