      "type": "tea",
      "kind": "龙眠山绿茶",
      "description": "桐城小花与龙眠山一带的茶园相联系，芽叶舒展像初开的花，茶汤清亮，香气清鲜，滋味醇和回甘。",
      "detail": "地方还有小花茶、龙眠茶等相关叫法，介绍中保留其茶名关系。它是桐城产区的绿茶，与舒城小兰花分别记录具体地域。",
