      "kind": "怀宁手工细面",
      "description": "怀宁的龙凤贡面，以精面粉配蛋、麻油和盐等手工拉制，面条细长成缕，煮熟后柔软，常配鸡汤或肉汤。",
      "detail": "手工反复拉伸使面条粗细较匀，先煮面再捞进备好的汤碗，能保留汤味。名称里的贡品故事流传于地方，细面工艺则可直接辨认。",
