      "description": "怀宁龙池庵、双尖山周边的地方绿茶，茶形扁直、显毫，茶汤绿亮，香气清长，味道鲜醇而有回甘。",
      "detail": "清河、黄墩等地都在相关产区线索中。茶名把龙池这个具体山地环境保留下来，能够补足安庆不同县域的茶叶分布。",
