      "description": "阳泉压饼以小麦、玉米、苦荞等面粉制成极薄饼片，配芝麻、花椒等调味，入口干脆，杂粮香逐渐释放。",
      "detail": "薄到透光的饼体与压制工艺是辨识点。不同杂粮搭配形成颜色、香味变化，作为便于携带的地方小食，适合从一片饼认识晋东面食。",
