      "city": "宁波",
      "name": "宁波汤圆",
      "type": "staples",
      "kind": "芝麻猪油馅汤团",
      "description": "宁波汤圆以水磨糯米粉作皮，常包黑芝麻、糖和猪油馅，煮熟后外皮柔糯，馅心油润香甜，地方也称汤团。",
      "detail": "元宵节、大年初一等节令常见汤团，圆形与团圆寓意相连。芝麻先炒香磨细，再与油糖成馅，形成小圆团里的浓香。",
