      "city": "金华",
      "name": "磐安云峰",
      "type": "tea",
      "kind": "地方绿茶",
      "description": "磐安云峰产于大盘山一带，茶条较挺直，色泽翠绿，汤色嫩绿明亮，香气清长、滋味鲜醇，是金华山地茶代表。",
      "detail": "茶园处于林密、湿润的山地环境，工艺兼有炒、烘环节。产地名与茶名让金华的茶叶可以细分到磐安，不只列一个省级名称。",
      "sources": [
        "city-1c9fc91bc7e332"
      ],
      "locality": "磐安县",
      "id": "flavor-zhejiang-af02039c34"
