      "description": "永康豆腐皮以黄豆制浆，制成薄而有韧性的豆皮，色泽金黄，可煮汤、切丝炒菜，也能包肉馅煎炸。",
      "detail": "豆皮本身是食材，不同于已做成的腐皮卷或素鸭。浸软后延展、包卷或叠层，能从同一种豆制品发展出多种地方菜。",
