      "name": "三门麻糍",
      "type": "staples",
      "kind": "捣制糯米面点",
      "description": "三门麻糍把糯米蒸熟后捣成黏团，压平、加芝麻糖等馅，再切块烙食，外层微香，里面柔糯而有韧性。",
      "detail": "地方有豆沙、豆类或咸菜等馅料变化，也有加入青料的做法。捣米、压合与切块体现家人共同制作的节令面点传统。",
