      "city": "台州",
      "name": "糊拉汰",
      "type": "staples",
      "kind": "天台薄煎饼",
      "description": "天台糊拉汰把小麦粉调成浆，沿热鏊摊成薄饼皮，烙熟后按喜好卷配菜，薄、柔与锅面焦香同时存在。",
      "detail": "“打浆”、摊皮与卷食构成完整做法，锅温和浆的稠度决定厚薄。这类面食把日常炒菜包进饼里，方便一口吃到多种食材。",
