      "description": "天台青饺与清明食俗相连，把艾青等植物与米粉制皮，包成饺形熟制，外皮青绿、柔糯，带植物清香。",
      "detail": "青团、青饼、青饺在江南有相通的节令背景，天台保留自己的形态与做法。具体馅料可咸可甜，应结合实物识别。",
