      "type": "dishes",
      "kind": "地方宴客菜组",
      "description": "仙居八大碗是当地成组上桌的宴客菜谱，肉、鱼、豆腐等搭配，讲究排列与菜序，体现地方婚宴和待客传统。",
      "detail": "仙居宴席把多道菜按一定次序组合上桌，地方又将菜名与八仙故事联系起来。成组菜式、排列与家庭礼俗，共同体现当地待客传统。",
