      "name": "赤豆元宵",
      "type": "staples",
      "kind": "豆汤小圆子",
      "description": "南京赤豆元宵将红豆与糯米小圆子同煮，常以藕粉勾芡，红豆绵软、小圆子柔糯，汤汁香甜浓稠。",
      "detail": "圆子通常体形较小，与整颗包馅汤圆吃法不同。红豆、米粉和藕粉各提供一种质地，组成一碗街头甜食。",
