      "name": "肉酿面筋",
      "type": "dishes",
      "kind": "油面筋包肉",
      "description": "无锡肉酿面筋把肉馅塞入清水油面筋，再配笋、香菇等烧煮，面筋吸汁，肉馅鲜香，外柔内实。",
      "detail": "空心油面筋为馅料提供包裹空间，烧煮后逐渐变软。它与只用面筋做的素菜不同，主体还包含猪肉。",
