      "kind": "甜酸炸鳝丝",
      "description": "梁溪脆鳝把鳝丝炸至松脆，再裹入咸甜、略带酸味的调味汁，色泽酱褐，入口脆香而有浓味。",
      "detail": "梁溪是与无锡相联系的水道地名。复炸有助于形成干脆口感，随后裹汁又增加甜酸层次。",
