      "type": "staples",
      "kind": "地方汤馄饨",
      "description": "无锡三鲜馄饨常以鲜肉、开洋、榨菜等成馅，配骨汤、蛋皮丝和豆干丝，薄皮与咸鲜汤味相伴。",
      "detail": "“三鲜”在不同地方配料不同，这里保留无锡的地方线索。馅料有肉香、海味与腌菜的不同鲜味来源。",
