      "kind": "糯米面煎馅饼",
      "description": "无锡玉兰饼以糯米粉等制皮，可包鲜肉、豆沙、芝麻等馅，平锅油煎后外脆里糯，常作早餐点心。",
      "detail": "地方名称与玉兰花开时节的故事相连。米粉皮提供黏糯，煎制又带出焦香，咸甜版本合并介绍。",
