      "description": "惠山油酥以面粉、油、芝麻和果仁等烘制，色泽金黄，口感酥松香甜，甜中有一点咸味。",
      "detail": "地方又有“金刚肚脐”的叫法，与圆鼓形态和寺院叙事相连。层次来自面皮与油酥，烤制后呈松散易化的口感。",
