      "type": "tea",
      "kind": "宜兴绿茶",
      "description": "宜兴阳羡雪芽茶形细直、显毫，汤色清澈，香气清雅、滋味鲜醇，是无锡宜兴茶区的具体代表。",
      "detail": "阳羡是宜兴的历史地域名，茶名也与苏轼相关诗句相联系。细嫩原料经制茶，形成挺秀茶形与鲜爽滋味。",
