      "kind": "宜兴调味豆干",
      "description": "宜兴和桥豆腐干以黄豆制坯，配酱油、糖和香料等，质地紧实，咸甜协调，越嚼越有豆香。",
      "detail": "压制使豆干不易散碎，调味形成当地产品风格。和桥有开洋、海鲜、香辣等版本，合并保留地域食品名称。",
