      "kind": "马蹄形酥点",
      "description": "江阴马蹄酥以面粉、赤豆、果仁等制作，外圈较厚、中间较薄，形似马蹄，入口酥、松、软相结合。",
      "detail": "马蹄酥在多地有同名点心，江阴保留自己的制作与消费传统。形态是名称来源，不必据此认定所有版本同一配方。",
