      "description": "徐州霸王别姬以鸡与鳖等同烹，常配火腿、香菇等，鲜汤把禽肉与水产味道结合，是当地宴席菜之一。",
      "detail": "菜名借项羽、虞姬的文化记忆，鸡与鳖又形成谐音联想。传说与菜式需要分别理解，食材组合是可直接辨认的特点。",
