      "description": "徐州蜜三刀以面团成形、划刀、油炸，再浸入糖浆，外观金黄油润，入口香甜，表层与内里有不同糖香。",
      "detail": "“蜜”与浸糖工序相连，不必然表示只用蜂蜜。地方糕点经营让它成为徐州有具体名称的传统甜点。",
