      "kind": "地方浓汤",
      "description": "徐州啥汤是当地早餐汤食，以肉、骨等熬出浓香，常配薄饼等面食，一碗热汤与主食组合成日常早饭。",
      "detail": "地方把它与彭祖、雉羹等故事相联系。不同汤馆配料各异，认识这项食品时以肉香、稠度和搭配吃法为主要线索。",
