      "description": "丰县烧饼用面粉、油和五香调料等制作，在两口铁锅组成的炉具中烤熟，外脆里暄，麦香与芝麻香相合。",
      "detail": "当地把制作称作“打烧饼”，锅炉结构和木炭火形成特有的烤制环境。与薄煎饼相比，它的饼体更厚、更松软。",
