      "description": "徐州烙馍把小麦面团擀薄，在热鏊上快速烙熟，饼皮柔韧，可卷入菜、蛋或肉，是当地常见面食。",
      "detail": "薄面皮在热鏊上迅速熟制，仍保留柔韧口感，适合卷菜。它可与汤、炒菜搭配，也能分块同食，是徐州餐桌灵活的主食。",
