      "name": "太仓肉松",
      "type": "dishes",
      "kind": "炒制绒状肉食",
      "description": "太仓肉松将猪后腿精肉等熟制、拆松、炒干，肉纤维细长蓬松，入口咸甜而有肉香，常用于佐粥或搭配糕点。",
      "detail": "水分逐渐去除，肉从整块变成细绒，形成肉松独特质地。太仓是苏州下辖县级市，保留地名识别地方熟肉传统。",
