      "name": "沙洲优黄",
      "type": "alcohol",
      "kind": "张家港黄酒品牌",
      "description": "沙洲优黄来自张家港地方酿酒，以米类发酵成黄酒，酒体清透，风味醇甜，有不同干甜程度的产品。",
      "detail": "沙洲是与张家港相联系的历史地域名。黄酒属于酿造酒，原料、发酵和贮存形成酒香，与蒸馏白酒的工艺不同。",
