      "type": "seasoning",
      "kind": "糟香液体调味品",
      "description": "太仓糟油以糟汁等配制，具有糟香、咸鲜和酱色，可用于糟禽、鱼片、虾等食物，是当地具体的调味品。",
      "detail": "名字虽有“油”，主要用途是糟味液体调料，不等于炒菜油。它与太仓酿酒、酱园传统相连，液体把发酵香气带入菜肴。",
