      "city": "盐城",
      "name": "滨海香肠",
      "type": "dishes",
      "kind": "地方腌制肉肠",
      "description": "滨海香肠以猪肉和当地调味配方加工，熟后肉香浓郁，切片可见肥瘦层次，是盐城滨海的地方肉食。",
      "detail": "制作把肉馅、调味和灌肠结合，食用时蒸熟切片。当地有以传统配方加工的生产者，食品名称保留滨海这一县域归属。",
