      "city": "盐城",
      "name": "五醍浆酒",
      "type": "alcohol",
      "kind": "滨海地方白酒",
      "description": "五醍浆酒产于盐城滨海八滩一带，以高粱及麦类制曲酿造，酒体有窖香、绵甜风格，是当地白酒。",
      "detail": "酿造把制曲、发酵和蒸馏等工序结合，具体酒度随产品而异。它与盐城的湖蟹、香肠等食品共同构成滨海地方餐桌的一部分。",
      "sources": [
        "city-9f276947a875d9"
      ],
      "locality": "滨海县",
      "id": "flavor-jiangsu-04e6a5fd14"
