      "city": "盐城",
      "name": "戚桥歪子茶干",
      "type": "dishes",
      "kind": "五香豆腐干",
      "description": "阜宁戚桥歪子茶干以大豆加工、卤制调味，颜色褐润、口感紧实，有五香、辣味等不同口味。",
      "detail": "茶干可作为零食，也可佐餐；名称中的“茶”是食品习惯叫法，原料主体仍是大豆，不是用茶树鲜叶制成的茶。",
