      "city": "扬州",
      "name": "千层油糕",
      "type": "staples",
      "kind": "糖油分层蒸糕",
      "description": "扬州千层油糕以发酵面团与糖、油反复叠层后蒸熟，切面层次清楚，口感绵软、甜润，是扬州茶点。",
      "detail": "面团的发酵和擀叠使糕体既松软又有层次，常切成菱形。它与翡翠烧麦常被并提，体现扬州早茶里精细的面点工艺。",
