      "kind": "青菜甜馅烧麦",
      "description": "扬州翡翠烧麦以薄皮包青菜叶、糖油等馅，蒸后馅色碧绿、入口甜润，是和千层油糕并列的当地茶点。",
      "detail": "青菜细馅透过薄皮呈现绿色，“翡翠”由此形容其外观。部分做法会用火腿末、猪油提香，咸味也用来衬托甜味。",
