      "description": "扬州虾籽饺面把细面、薄皮馄饨同放一碗，以虾籽等调成鲜汤；这里的“饺”沿用地方对馄饨的称呼。",
      "detail": "面条带来筋道口感，馄饨有肉馅和薄皮的柔软，虾籽使汤味更鲜。一碗兼有两种面食，是扬州地方汤面的一种组合。",
