      "description": "高邮咸鸭蛋以鸭蛋盐腌后熟制，蛋白咸香、蛋黄细沙而油润，是扬州高邮具有明确地方名称的食品。",
      "detail": "当地鸭业与蛋品加工相连，咸蛋既可佐粥，也进入粽子、点心等馅料。袁枚《随园食单》也曾记述高邮腌蛋的风味。",
