      "description": "仪征绿杨春茶产于扬州仪征丘陵地带，茶汤翠绿明亮、滋味鲜醇，是当地有具体产区名称的绿茶。",
      "detail": "月塘、捺山等地的丘陵环境与茶园相连，鲜叶经杀青、揉制、干燥成茶。绿杨春在这里指当地茶名，区别于茶店的分店地址。",
