      "description": "镇江糖醋萝卜干把萝卜经腌制、晾制等处理后用糖醋调味，口感脆韧，甜酸中带醋香，是当地佐餐酱菜。",
      "detail": "萝卜脱水后更容易吸收调味汁，保留咀嚼感。它用来配粥、配饭，也体现镇江香醋在日常小菜中的一种用法。",
