      "city": "淄博",
      "name": "桓台金丝鸭蛋",
      "type": "dishes",
      "kind": "马踏湖腌鸭蛋",
      "description": "桓台金丝鸭蛋以马踏湖一带鸭蛋腌制，熟后蛋黄沙润、有油香，蛋黄与蛋白交界可见油润纹理。",
      "detail": "“金丝”形容剖开鸭蛋时的色泽和油圈。湖区养鸭与蛋品加工相连，使鸭蛋成为淄博桓台一种具体的地方食品。",
