      "description": "峄城石榴产自枣庄峄城，果粒饱满、汁水充足，甜酸风味随品种而变化，是当地具有明确产区的水果。",
      "detail": "当地石榴园与鲜果、果汁及叶片加工相连，剥开的籽粒也是石榴最直接的食用部分。此项记录产地鲜果，不与榴叶茶重复。",
