      "description": "山亭花椒来自枣庄山亭，椒皮有浓郁辛香与麻味，可用于炖肉、炒菜或制作花椒油，是当地调味食材。",
      "detail": "花椒的香气主要来自果皮，干制后便于储存、调味。山亭地方种植有不同花椒品种，香麻程度和外观会有差别。",
