      "city": "东营",
      "name": "河口锅子饼",
      "type": "staples",
      "kind": "薄饼包菜煎食",
      "description": "河口锅子饼把麦面薄饼与韭菜、茴香等馅料结合，用平底锅煎制，饼香与菜香相融，是东营河口地方面食。",
      "detail": "馅料有荤、素及海鲜等变化，面皮烙熟后卷包，强调酥而不硬的口感。它反映黄河三角洲麦面主食与菜蔬的搭配。",
