      "description": "烟台咸鱼饼子把腌晒海鱼煎香，再配玉米面饼同食，咸鲜鱼味与谷物香相互搭配，是胶东沿海地方餐食。",
      "detail": "海鱼腌晒使鲜味集中，玉米饼提供松香主食口感。这一组合与渔家生活相连，一份食物中同时保留水产和杂粮面食。",
