      "type": "staples",
      "kind": "湖区杂粮薄饼",
      "description": "微山湖煎饼以高粱、小麦、玉米、小米等谷物摊烙，可用单一谷物，也可混合，颜色和香气随用料变化。",
      "detail": "谷物糊在鏊面薄烙成形，有的还配芝麻、菱米等原料。湖区食品资源进入煎饼，使它不只是单一麦面薄饼。",
