      "description": "蜜制红三刀是济宁金乡传统面点，以面粉、糖稀、芝麻等制坯，油炸后浸浆，外酥内松、香甜有嚼感。",
      "detail": "面坯表面划三刀再炸制，糖浆进入后形成红亮色泽和甜润内部。它以切口形态得名，与普通糖块的原料和工艺不同。",
