      "description": "接山千层饼又叫瓤子饼，来自泰安东平接山一带，麦面中加油、盐和花椒等，外黄里暄、层次清楚。",
      "detail": "面皮包叠出多层后烙熟，热时酥软，放凉仍有韧劲。两个名称指向同一种地方饼，既保留“瓤子”的俗名，也保留接山地名。",
