      "description": "泰山君子茶以茶树春梢加工，干茶条形、色绿，冲泡后汤色黄绿、味鲜醇，是泰安地方绿茶品牌。",
      "detail": "它的原料是茶树鲜叶，和桑叶、槐蕾等代用茶不同。采芽、杀青、做形与干燥，使茶叶形成清香和较鲜爽的风格。",
