      "description": "泰山豆腐宴以豆腐制作多种菜肴，烧、炖、煎等做法各有口感，是泰安围绕地方豆腐形成的宴席风味。",
      "detail": "泰安饮食中常谈白菜、豆腐与水的“三美”，豆腐宴则把豆腐展开为多种菜式。烧、煎、炖等工序带来不同口感，形成地方宴席风味。",
