      "description": "威海海鲜手擀面用较有筋道的手擀面配虾、蛤蜊、鱿鱼等海鲜，麦香与海味结合，是当地沿海面食。",
      "detail": "面团和得较硬、擀开切条，煮后仍有嚼劲，海鲜则为汤面增加鲜味。不同渔获季节会带来不同配料组合。",
