      "description": "九仙煎饼来自日照五莲九仙山一带，以去皮地瓜等加工摊烙，饼身柔韧，可配豆腐、大葱、辣椒等卷食。",
      "detail": "它与常见麦面煎饼的原料侧重不同，地瓜为饼带来甜香。薄饼卷入当地豆腐、菜蔬后，成为山地日常一餐的组合。",
