      "name": "孟家包子",
      "type": "staples",
      "kind": "猪肉灌汤蒸包",
      "description": "孟家包子是聊城具名灌汤面点，以猪肉、葱姜、冻子等制馅，面皮蒸后柔软，皮薄、汁多、馅味鲜。",
      "detail": "冻子在加热中融化形成汤汁，包制时需让面皮托住馅料。“孟家”保留了制作家族与店铺的名称，连接地方饮食记忆。",
